const o = state.order;
const subtotal = o.items.reduce((s, i) => s + i.qty * i.price, 0);
const tax = Math.round(subtotal * 0.21 * 100) / 100;
const shipping = subtotal >= 100 ? 0 : 9.9;
const total = Math.round((subtotal + tax + shipping) * 100) / 100;
log(`order ${o.id}: subtotal ${subtotal}, total ${total}`);
return { values: { invoice: { orderId: o.id, subtotal: subtotal, tax: tax, shipping: shipping, total: total } } };

const o = state.order;
const reserved = o.items.map(i => ({ sku: i.sku, qty: i.qty, warehouse: i.sku.charCodeAt(0) % 2 === 0 ? 'north' : 'south' }));
log(`order ${o.id}: ${reserved.length} lines reserved`);
return { values: { reservation: { orderId: o.id, lines: reserved } } };

const o = state.order, inv = state.invoice, r = state.reservation;
const warehouses = [...new Set(r.lines.map(l => l.warehouse))];
const shipment = { orderId: o.id, customer: o.customer, packages: warehouses.length, from: warehouses, charge: inv.total, status: 'ready' };
log(`order ${o.id}: ${shipment.packages} package(s), ${inv.total} charged`);
return { values: { shipment: shipment } };
